`timescale 1ps / 1ps

module PH1P_PHY_HR_PAD_V2 (
        ipad,
        opad,
        bpad,
        rst,
        ce,
        isclk,
        ipclk,
        osclk,
        opclk,
        ts,
        doq,
        di,
        diq,
        odly_in,
        odly_out,
        idly_in,
        in_dly,
        out_dly,
        pdr,
        dl_tdi,
        dl_tdo,
        diff_in,
        diff_out,
        rdiff_enb,
        dl_in_rtn,
        dl_out_rtn,
        lb_enb,
        te_n,
        ck_dl_o,
        dl_ck_o,
        rst_align
);
input            dl_in_rtn;   //[tag:hardwire]
output           dl_out_rtn;  //[tag:hardwire]
input            idly_in;
input            odly_in;
input            dl_tdi;      //[tag:hardwire]
output           dl_tdo;      //[tag:hardwire]
output           odly_out;
input            ipad;        //[tag:virtual]
output           opad;        //[tag:virtual]
inout            bpad;        //[tag:virtual]
input            rst;         //[tag:reset]
input            ce;
input            isclk;       //[tag:clk]
input            ipclk;       //[tag:clk]
input            osclk;       //[tag:clk]
input            opclk;       //[tag:clk]
input            ts;
input  [9:0]     doq;
output           di;
output [9:0]     diq;
input  [7:0]     in_dly;
input  [7:0]     out_dly;
input            diff_in;     //[tag:virtual]
output           diff_out;    //[tag:virtual]
input            rdiff_enb;
input            lb_enb;
input            pdr;
input            te_n;
output           ck_dl_o;
output           dl_ck_o;
input            rst_align;

tri1            rst;
tri1            ce;
tri1            isclk;
tri1            ipclk;
tri1            osclk;
tri1            opclk;
tri1            ts;
tri1  [9:0]     doq;
tri1  [7:0]     in_dly;
tri1  [7:0]     out_dly;
tri1            pdr;
tri1            te_n;
tri1            lb_enb;
//////////////////////////////////////IOL/////////////////////////////////////////////////////
parameter LB_TO_DI          = "DISABLE";        // "ENABLE", "DISABLE" :[mc1_indly_byp]
parameter INRST             = "0";              // "0", "PROGRST" : [mc1_inrst_en]
parameter ISCLKSWI          = "SIG";            // "SIG", "INV" : [mc1_isclk_inv]
parameter IPCLKSWI          = "SIG";            // "SIG", "INV" : [mc1_ipclk_inv]
parameter OSCLKSWI          = "SIG";            // "SIG", "INV" : [mc1_osclk_inv]
parameter OPCLKSWI          = "SIG";            // "SIG", "INV" : [mc1_opclk_inv]
parameter INDELMUX          = "NODEL";          // "NODEL", "FIXDEL", "PROGDEL" : [mc1_indly_md]
parameter OUTDELMUX         = "NODEL";          // "NODEL", "FIXDEL", "PROGDEL" : [mc1_outdly_md]
parameter INDEL             = 1;                // 1~256
parameter OUTDEL            = 1;                // 1~256
parameter IDDRMODE          = "OFF";            // "OFF" , "SDFF" , "DDRX1" , "DDRX1_PIPE" , "DDRX2" , "DDRX3P5" , "DDRX4" , "DDRX5" : [mc1_ix2p,mc1_ix_md,mc1_even_idata_pnsamp_en,mc1_iload_sel,mc1_rst_async]
parameter ODDRMODE          = "OFF";            // "OFF" , "SDFF" , "DDRX1" , "DDRX2" , "DDRX3P5" , "DDRX4" , "DDRX5" : [mc1_ox_md,mc1_oload_sel,mc1_rst_async,mc1_outrst_md]
parameter TSMUX             = "1";              // "1" , "0" , "TS" , "INV" , "TS_REG" , "TS_REG_INV" : [mc1_ts_sel,mc1_tsinv,mc1_rst_async]
parameter TO_REGSET         = "RESET";          // "RESET", "SET" : [mc1_ts_set]
parameter RSTMUX            = "RST";            // "RST" , "INV" : [mc1_rst_inv_en]
parameter OUTRST            = "0";              // "0", "PROGRST" : [mc1_outrst_en]
parameter OUTCE             = "PROGCE";         // "1", "PROGCE"  : [mc1_outce_en]
parameter IDLYSYNC          = "DISABLE";        // "ENABLE" , "DISABLE" : [mc1_idly_sync_en]
parameter ODLYSYNC          = "DISABLE";        // "ENABLE" , "DISABLE" : [mc1_odly_sync_en]
parameter INCE              = "PROGCE";         // "1", "PROGCE"  : [mc1_ince_en]
parameter IN_REGSET         = "RESET";          // "RESET", "SET" : [mc1_in_set]
parameter DO_REGSET         = "RESET";          // "RESET", "SET" : [mc1_do_set]
parameter GSR               = "ENABLE";         // "ENABLE", "DISABLE" : [mc1_dis_gsr]
parameter CEMUX             = "CE";             // "CE", "INV"    : [mc1_ce_inv_en]
parameter OUTRST_MODE       = "ASYNC";          // "SYNC" , "ASYNC" : [mc1_rst_async]
parameter INRST_MODE        = "ASYNC";          // "SYNC" , "ASYNC" : [mc1_inrst_md,mc1_rst_async]
parameter IOTEST            = "DISABLE";        // "ENABLE","DISABLE" : [mc1_test_en]
parameter ODLYSRC           = "CASCADE";        // "IOB" , "SOFT" , "CASCADE" , "ODDR"  : [mc1_pib_odlyin_en,mc1_outdly_byp,mc1_iobdly_in_en,mc1_dly_cas_en]
parameter IDLYSRC           = "CASCADE";        // "CASCADE","SOFT", "IOB" : [mc1_pib_idlyin_en,mc1_dly_cas_en]
parameter PCLK_POS_NEG_EN   = "DISABLE";        // "DISABLE" , "ENABLE"   : [mc1_oserdes_pclk_neg_en]
parameter OSERDESMODE       = "SERDES";         // "SERDES"  , "DDR"      : [mc1_oserdes_ddr_mode,mc1_oload_sel]
parameter ISERDESMODE       = "SERDES";         // "SERDES"  , "DDR"      : [mc1_iserdes_ddr_mode,mc1_iload_sel,mc1_iserdes_ddr_clk_en]
parameter LOWPOWEREN        = "DISABLE";        // "DISABLE" , "ENABLE"   : [mc1_lowpower_en]
parameter IPCLK_POS_NEG_EN  = "DISABLE";        // "DISABLE" , "ENABLE"   : [mc1_ipclk_neg_samp_en]
parameter ISERDESSRC        = "NORMAL";         // "NORMAL"  , "DELAYCAS" : [mc1_iddr_dly_cas_en]
parameter DLYTEST           = "DISABLE";        // "DISABLE" , "ENABLE"   : [mc1_dl_test_en]
parameter COMPONENTFIFOEN   = "DISABLE";        // "DISABLE" , "ENABLE"   : [mc1_component_fifo_en]
parameter IEVENDATASAMP     = "DISABLE";        // "DISABLE" , "ENABLE"   : [mc1_even_idata_pnsamp_en]
parameter DIRBYPEN          = "DISABLE";        // "ENABLE" , "DISABLE"   : [mc1_jclk_inv_en]
parameter DLY_TO_IOB_EN     = "ENABLE";         // "ENABLE" , "DISABLE"   : [mc1_pdiff_en]
parameter LVDS_EN           = "ENABLE";         // "ENABLE" , "DISABLE"   : [mc1_oddr_dly_cas_en]
//////////////////////////////////////IOL/////////////////////////////////////////////////////

//////////////////////////////////////IOB/////////////////////////////////////////////////////
parameter MODE              = "IN";           // "NONE", "IN", "OUT", "BI" : [mc1_rx_mode, mc1_tx_mode]
parameter DIFF_MODE         = "P";            // "P", "N","S" 
parameter IOTYPE            = "LVCMOS18";     //"LVTTL33" ,"LVCMOS33" , "LVCMOS25" , "LVCMOS18" , "LVCMOS15" , "LVCMOS12" , "HSTL18_I", "HSTL_I" , "SSTL18_I" , "SSTL15" , "SSTL15_R" ,"SSTL135" ,"SSTL12" , "POD12" , "HSUL12" ,  "DIFF_HSTL18_I"  ,"DIFF_HSTL_I"  , "DIFF_SSTL18_I" , "DIFF_SSTL15", "DIFF_SSTL15_R" , "DIFF_SSTL135" , "DIFF_SSTL12" , "DIFF_POD12" ,  "DIFF_HSUL12" , "LVDS33", "LVDS25" ,"MINI_LVDS", "SUB_LVDS", "LVDS18", "TMDS33", "LVDS33_E", "LVDS25_E" , "LVDS18_E", "VREF_DRIVE": [mc1_tx_mode,mc1_rx_mode,mc1_ensrc,mc1_ensnk,mc1_drv_st_p,mc1_drv_st_n,mc1_inhys,mc1_odt_st_p,mc1_odt_st_n,mc1_rdiff_en,mc1_lvds_slew,mc1_inthres,mc1_odt_sel,mc1_duty_adj_p,mc1_duty_adj_n,mc1_do_sel,mc1_slew]
//parameter ODT             = "OFF";          // "OFF", "50", "100" : [mc1_odt_st_p,mc1_odt_st_n,mc1_odt_sel]
//parameter SLEWRATE        = "SLOW";         // "SLOW", "MED", "FAST":[mc1_slew]
parameter DRIVE           = "8";            // "NONE" , "2", "4", "6" , "8" , "12" ,"16","FIXED": [mc1_ensrc,mc1_ensnk,mc1_drv_st_p,mc1_drv_st_n,mc1_duty_adj_p,mc1_duty_adj_n,mc1_do_sel]
//parameter PCICLAMP        = "OFF";          // "OFF", "ON":[mc1_clamp]
parameter PULLMODE        = "NONE" ;        // "PULLUP" , "PULLDOWN" , "NONE" , "KEEPER" : [mc1_pu_md,mc1_pd_md,mc1_usr_pd,mc1_usr_pu_n]
